insert into public.topics (slug, title, description, is_published) values
  ('housing_support', 'Жилищная помощь и социальное жильё', 'Помощь на аренду, социальное жильё и перерасчёт платы в государственном жилье.', true),
  ('child_disability', 'Пособие на ребёнка с инвалидностью', 'Правила выплаты пособия на ребёнка с инвалидностью, включая пребывание в учреждении.', true),
  ('tax_credits', 'Налоговые льготные единицы', 'Льготные налоговые единицы и семейные налоговые права.', true)
on conflict (slug) do update set
