insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id, v.slug, v.title, v.short_answer, v.answer, v.steps, v.documents,
       v.follow_up_questions, v.caveats, '[]'::jsonb, v.keywords, v.search_text,
       true, '2026-09-17', true
from (values
  ('severance','kz-childcare-resignation','severance-childcare-resignation',
   'Пицуим при увольнении для ухода за ребёнком после родов',
   'Работница, которая увольняется в течение 9 месяцев со дня рождения ребёнка именно для ухода за ним, при выполнении условий может получить пицуим как уволенная работодателем.',
   'Основные условия: увольнение должно быть связано с уходом за ребёнком, трудовые отношения с работодателем должны длиться не менее года, а прекращение работы должно попасть в девятимесячный период со дня рождения ребёнка. Работодателю нужно письменно сообщить, что увольнение связано с уходом за ребёнком, и соблюсти срок предварительного уведомления. Для пособия по безработице такое увольнение обычно означает ожидание 90 дней после первой регистрации в Службе занятости, если нет другого основания для немедленной выплаты.',
   array['Подайте работодателю письменное заявление, прямо указав, что увольняетесь для ухода за ребёнком.','Рассчитайте срок предварительного уведомления так, чтобы фактическое прекращение работы пришлось на первые 9 месяцев после рождения ребёнка.','После прекращения работы получите форму 161 и расчёт пицуим.','Если планируете авталу, зарегистрируйтесь в Службе занятости как можно раньше.'],
   array['Письменное заявление об увольнении','Документы о дате рождения ребёнка','Форма 161 после окончания работы'],
   array['Вы проработали у этого работодателя не менее одного года?'],
   array['Для отца действуют дополнительные условия.','Право на авталу и право на пицуим проверяются отдельно.'],
   array['после родов','9 месяцев','уход за ребенком','уход за ребёнком','декрет','пицуим','увольнение после рождения'],
   'родила четыре месяца назад декрет отпуск по уходу за ребёнком ребенком не возвращаться на работу увольнение после родов 9 месяцев пицуим выходное пособие уход за ребенком один год стажа 90 дней автала'),

  ('disability','btl-impairment-book','disability-migraine-criteria',
   'Мигрень и медицинский процент инвалидности',
   'Хронические первичные головные боли могут давать медицинский процент инвалидности; оценка зависит от частоты, тяжести и реакции на профилактическое лечение.',
   'Для головных болей средней или тяжёлой степени с частотой не менее 4 дней в месяц применяются ступени медицинского процента: 5% без профилактического лечения специальным препаратом, 10% при отсутствии эффекта от одного профилактического препарата, 20% при отсутствии эффекта как минимум от двух препаратов и 40% при тяжёлых головных болях без эффекта как минимум от трёх профилактических препаратов. Для высокой ступени особенно важны документы невролога и история приобретения лекарств. Сам медицинский процент ещё не гарантирует денежное пособие по общей инвалидности: отдельно проверяется влияние состояния на способность работать и другие условия права.',
   array['Ведите медицинскую документацию о частоте и тяжести приступов.','Сохраняйте назначения невролога и сведения о профилактических препаратах и результате лечения.','При подаче заявления приложите неврологические заключения и выписку о лекарствах из больничной кассы.'],
   array['Заключение невролога','История лечения и профилактических препаратов','Выписка приобретённых лекарств'],
   array['Сколько дней в месяц бывают приступы?','Сколько профилактических препаратов уже были испробованы без достаточного эффекта?'],
   array['Медицинский процент и право на ежемесячное пособие — не одно и то же.','Окончательное решение принимает медицинская комиссия Битуах Леуми.'],
   array['мигрень','головная боль','невролог','5%','10%','20%','40%','профилактическое лечение'],
   'мигрень мигрени сильные головные боли два раза в неделю невролог лечение инвалидность 5 10 20 40 процентов четыре дня в месяц профилактические лекарства финансовая поддержка'),

  ('disability','btl-disability-income-65','disability-income-65-2026',
   'Заработок при степени нетрудоспособности 65% в 2026 году',
   'При степени потери трудоспособности 65% таблица Битуах Леуми на 2026 год показывает нулевое уменьшение пособия при заработке до 12 071 шекеля брутто в месяц.',
   'По таблице, действующей с 01.01.2026, при доходе от работы от 2 892 до 12 071 шекеля уменьшение пособия для степени нетрудоспособности 65% равно нулю. Размер самой выплаты зависит от состава семьи и надбавок. При более высоком заработке пособие начинает уменьшаться по таблице Битуах Леуми.',
   array['Сверьте в решении Битуах Леуми именно степень потери трудоспособности 65%.','Сравнивайте с зарплатой брутто, а не суммой на руки.','При изменении зарплаты проверяйте актуальную таблицу соответствующего года.'],
   array['Решение о степени потери трудоспособности','Тлуш с зарплатой брутто'],
   array['Указана ли в решении именно степень потери трудоспособности 65%?'],
   array['Пороговые суммы ежегодно обновляются.','Доплаты за детей и супруга зависят от состава семьи.'],
   array['65% нетрудоспособности','12071','12 071','зарплата','не уменьшили пособие','2026'],
   'степень нетрудоспособности 65 процентов медицинская инвалидность 71 зарплата сколько можно зарабатывать пособие не уменьшили 12071 12 071 дети армия инвалидность работа 2026'),

  ('old_age','btl-old-age-income-supplement','old-age-income-supplement-2026',
   'Доплата до прожиточного минимума к пособию по старости в 2026 году',
   'Право на доплату проверяется по доходам обоих супругов и другим условиям; для пары младше 70 лет максимальная сумма пособия по старости с доплатой составляет 6 912 шекелей с 01.01.2026.',
   'Битуах Леуми проверяет доходы заявителя и супруга по видам дохода. Для пары младше 70 лет сумма пособия по старости с доплатой до прожиточного минимума составляет до 6 912 шекелей в месяц с 01.01.2026. Наличие дополнительных доходов или выплат может уменьшить доплату или исключить право, но сравнивать только общую сумму всех поступлений без проверки их типа недостаточно.',
   array['Составьте список всех регулярных доходов обоих супругов по видам.','Проверьте доходы по таблице Битуах Леуми для доплаты к пособию по старости.','Отдельно укажите финансовые активы и другие источники дохода.'],
   array['Решения Битуах Леуми о пособиях','Подтверждения пенсионных и страховых выплат','Сведения о других доходах'],
   array['Какие именно выплаты получает каждый супруг и из какого источника?'],
   array['Максимальная сумма зависит от возраста и состава семьи.','Правила учитывают не только выплаты Битуах Леуми, но и другие доходы и имущество.'],
   array['социальная надбавка','доплата до прожиточного минимума','6912','6 912','пособие по старости','пара'],
   'социальная надбавка пособие по старости супруг инвалидность особые услуги страховая выплата доходы супругов 6912 6 912 прожиточный минимум доплата 2026'),

  ('old_age','btl-old-age-assets','old-age-income-supplement-assets-2026',
   'Как финансовые активы влияют на доплату к пособию по старости',
   'Деньги и финансовые активы могут учитываться при проверке доплаты: для пары первые 62 292 шекеля стоимости финансового актива не влияют на право, а на превышение рассчитывается условный доход по правилам Битуах Леуми.',
   'С 01.01.2026 для пары финансовый актив стоимостью до 62 292 шекелей не влияет на доплату. Из суммы сверх этого порога Битуах Леуми рассчитывает условный ежемесячный доход по установленной процентной ставке; для более крупных активов действует ступенчатый расчёт. Поэтому закрытый банковский счёт или накопления нельзя автоматически игнорировать при проверке права.',
   array['Укажите текущую стоимость финансовых активов пары.','Проверьте расчёт условного дохода в официальном калькуляторе Битуах Леуми.'],
   array['Банковская выписка или подтверждение остатка'],
   array['Какова текущая сумма финансовых активов пары?'],
   array['Происхождение денег само по себе не всегда исключает их из проверки; нужно смотреть правила конкретного актива.'],
   array['банковский счёт','200000','активы','имущество','социальная надбавка','доплата'],
   'закрытый банковский счет 200000 200 000 шекелей выходное пособие накопления активы социальная надбавка пособие по старости доплата прожиточный минимум'),

  ('old_age','kz-old-age-benefits','old-age-supplement-benefits',
   'Льготы при пособии по старости с доплатой до прожиточного минимума',
   'Получение пособия по старости с доплатой до прожиточного минимума открывает дополнительные льготы, включая скидки на арнону, электричество и другие права.',
   'Не все льготы появляются только из-за достижения пенсионного возраста. Существенная часть дополнительных скидок связана именно с получением доплаты до прожиточного минимума или с отдельным основанием. Поэтому сначала важно знать, будет ли назначена такая доплата, а затем проверить правила каждой конкретной льготы.',
   array['Сначала уточните, назначено ли пособие по старости с доплатой до прожиточного минимума.','После назначения проверьте отдельно арнону, электричество, воду и другие льготы.'],
   array['Решение Битуах Леуми о пособии по старости и доплате'],
   array['Будет ли супруг получать доплату до прожиточного минимума к пособию по старости?'],
   array['Набор льгот зависит от вида пособия и условий конкретной льготы.'],
   array['скидки пенсионерам','социальная надбавка','льготы','пособие по старости','счета'],
   'супруг выходит на пенсию счета оформлены на меня переписывать счета скидки социальная надбавка пособие по старости льготы арнона электричество вода'),

  ('old_age','kz-old-age-arnona','old-age-discount-account-holder',
   'На чьё имя должны быть оформлены счета для льгот пенсионера',
   'Не нужно заранее переписывать все счета: требования зависят от конкретной льготы. Для скидки на арнону получатель должен быть зарегистрирован как фактический держатель объекта; для скидки на электричество данные получателя должны совпадать с клиентом по договору.',
   'Для арноны право реализует человек, зарегистрированный в муниципалитете как держатель объекта. Для скидок на электричество обычно требуется, чтобы договор был зарегистрирован на имя и идентификационный номер получателя льготы. Поэтому переносить все бытовые счета заранее не требуется: сначала определите конкретные льготы, а затем переоформляйте только те счета, где это условие действительно нужно.',
   array['Определите конкретные льготы, на которые есть право.','Проверьте, кто зарегистрирован держателем объекта по арноне.','Если положена скидка на электричество, проверьте имя клиента в договоре с электрокомпанией.'],
   array['Решение о праве на соответствующую льготу','Счёт арноны или договор электроснабжения'],
   array['Какая конкретно скидка вас интересует: арнона, электричество, вода или другая?'],
   array['Правила переоформления различаются для разных поставщиков и льгот.'],
   array['переписать счета','на имя супруга','арнона','электричество','скидка пенсионеру'],
   'все счета на меня супруг выходит на пенсию переписывать на супруга скидки арнона электричество получатель льготы имя клиента договор держатель объекта'),

  ('housing_support','gov-public-housing-rent-discount','public-housing-rent-income-recalc',
   'Перерасчёт платы в социальном жилье при изменении дохода',
   'Плата в социальном жилье рассчитывается с учётом состава семьи и её доходов; при существенном изменении дохода можно подать обновлённые сведения и просить новый расчёт.',
   'Министерство строительства и жилищного хозяйства определяет льготную квартплату в социальном жилье по составу семьи и совокупному доходу взрослых членов семьи. Если доход изменился, можно подать новый запрос и документы о доходах до очередного двухлетнего пересмотра. В определённых случаях скидка может быть предоставлена ретроактивно: обычно до 6 месяцев, а для домохозяйств, живущих только на пособия существования Битуах Леуми, до 24 месяцев.',
   array['Письменно сообщите компании, управляющей жильём, об изменении фактически получаемого дохода.','Приложите актуальные подтверждения доходов или прекращения выплат.','Попросите письменный перерасчёт квартплаты и, если применимо, ретроактивной скидки.'],
   array['Актуальные подтверждения доходов','Подтверждение прекращения прежней выплаты','Последний расчёт квартплаты'],
   array['Вы уже сообщали компании письменно о прекращении этой пенсии?'],
   array['Точный период ретроактивного перерасчёта зависит от основания льготы и документов.'],
   array['Амигур','хостел','русская пенсия','перерасчёт','социальное жильё','квартплата'],
